entries[84408] = { ["name"] = "R19 Threatfinder", ["text"] = "2 sec cast 5\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (6), Handful of Obsidium Bolts (6), Alicite (2)\nR19 Threatfinder\n80\nUse: Attaches a permanent scope to a bow or gun that increases ranged hit rating by 88.\n\nAttaching this scope to a ranged weapon causes it to become soulbound." }
entries[84409] = { ["name"] = "Volatile Seaforium Blastpack", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nHandful of Obsidium Bolts , Electrified Ether (2)\nRequires Engineering\n(425)\nUse: Blasts open locked doors and chests that require lockpicking skill of 525 and below." }
entries[84410] = { ["name"] = "Safety Catch Removal Kit", ["text"] = "2 sec cast 5\nTools: Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (10), Handful of Obsidium Bolts (10)\nSafety Catch Removal Kit\n80\nUse: Removes the safety mechanism from a bow or gun, increasing its ranged haste rating by 88.\n\nUsing this kit causes the bow or gun to become soulbound." }
entries[84411] = { ["name"] = "High-Powered Bolt Gun", ["text"] = "4 sec cast 5\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (10), Handful of Obsidium Bolts (8), Electrified Ether (4)\nHigh-Powered Bolt Gun\nBinds when used\nRequires Engineering\n(450)\nUse: Fires several charged bolts at an enemy for 8860 damage and briefly interrupts casting. Consumes a Handful of Obsidium Bolts each time it's fired. (2 Min Cooldown)\n\"Nearly as complicated to operate as it is to make.\"" }
entries[84412] = { ["name"] = "Personal World Destroyer", ["text"] = "2 sec cast 5\nTools: High-Powered Bolt Gun , Blacksmith Hammer\nReagents:\nObsidium Bar (10), Handful of Obsidium Bolts (8), Electrified Ether (8)\nPersonal World Destroyer\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Personal World Destroyer." }
entries[84413] = { ["name"] = "De-Weaponized Mechanical Companion", ["text"] = "2 sec cast 5\nTools: High-Powered Bolt Gun , Arclight Spanner\nReagents:\nObsidium Bar (12), Handful of Obsidium Bolts (4), Electrified Ether (8), Jasper (2)\nDe-Weaponized Mechanical Companion\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your De-Weaponized Mechanical Companion." }
entries[84415] = { ["name"] = "Lure Master Tackle Box", ["text"] = "5 sec cast 5\nTools: Blacksmith Hammer , High-Powered Bolt Gun\nReagents:\nElementium Bar (20), Handful of Obsidium Bolts (4)\nLure Master Tackle Box\nBinds when equipped\n36 Slot Tackle Box" }
entries[84416] = { ["name"] = "Elementium Toolbox", ["text"] = "5 sec cast 5\nTools: Blacksmith Hammer\nReagents:\nElementium Bar (15), Volatile Earth (12)\nElementium Toolbox\nBinds when equipped\n36 Slot Engineering Bag\n\"Possibly the finest toolbox ever made, embellished with gold inlay.\"" }
entries[84417] = { ["name"] = "Volatile Thunderstick", ["text"] = "2 sec cast 5\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nElectrified Ether (2), Hardened Elementium Bar (5), Volatile Fire (6)\nVolatile Thunderstick\nBinds when equipped\nRanged Gun\n958 - 1,781 Damage Speed 2.80\n(489.11 damage per second)\n+84 Agility\n+126 Stamina\n+ 56 Mastery\nDurability 75 / 75\n83\nEquip: Improves critical strike rating by 56." }
entries[84418] = { ["name"] = "Elementium Dragonling", ["text"] = "2 sec cast 5\nTools: Blacksmith Hammer , High-Powered Bolt Gun\nReagents:\nHandful of Obsidium Bolts (2), Electrified Ether (8), Elementium Bar (16), Embersilk Cloth (20)\nElementium Dragonling\nBinds when equipped\nUnique-EquippedTrinket\n+ 252 Mastery\n80\nRequires Engineering\n(475)\nUse: Activates your Elementium Dragonling to fight for you for 1 min. (5 Min Cooldown)" }
entries[84419] = { ["name"] = "Challenging Shout", ["text"] = "Instant 10 sec cooldown\nTaunts the target to attack you, but has no effect if the target is already attacking you." }
entries[84420] = { ["name"] = "Finely-Tuned Throat Needler", ["text"] = "2 sec cast 5\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nObsidium Bar (4), Electrified Ether (2), Hardened Elementium Bar (5)\nFinely-Tuned Throat Needler\nBinds when equipped\nRanged Crossbow\n993 - 1,844 Damage Speed 2.90\n(489.14 damage per second)\n+84 Agility\n+126 Stamina\nDurability 75 / 75\n83\nEquip: Improves critical strike rating by 49.\nEquip: Improves haste rating by 60." }
entries[84421] = { ["name"] = "Loot-a-Rang", ["text"] = "5 sec cast 5\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Elementium Bar (5), Electrified Ether (5)\nLoot-A-Rang\nBinds when used\nToy\nRequires Engineering\n(125)\nUse: Retrieves the loot from a nearby corpse. (10 Sec Cooldown)" }
entries[84424] = { ["name"] = "Invisibility Field", ["text"] = "5 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nHandful of Obsidium Bolts , Electrified Ether\nPermanently attaches thousands of tiny mirrors to your belt, allowing you to turn invisible while out of combat. Can be activated once every 5 min.\n\nCan only be used on your own belt, and doing so will cause it to become soulbound. Requires at least 500 skill in Engineering to use." }
entries[84425] = { ["name"] = "Cardboard Assassin", ["text"] = "5 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nSimple Wood (2), Handful of Obsidium Bolts\nPermanently attaches a tiny device on your belt, allowing you to create a Cardboard Assassin that enemies will attack. Lasts 15 sec. Can be used once every 5 min.\n\nCan only be used on your own belt, and doing so will cause it to become soulbound. Requires at least 500 skill in Engineering to use." }
entries[84426] = { ["name"] = "Felbreath", ["text"] = "Melee Range\n2.5 sec cast\nInflicts Fire damage to enemies in a cone in front of the caster." }
entries[84427] = { ["name"] = "Grounded Plasma Shield", ["text"] = "5 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nElectrified Ether (3)\nPermanently attaches grounded plasma generators to your belt, allowing you to activate a powerful shield that absorbs 16200 to 19800 damage. Usable once every 5 minutes.\n\nCan only be used on your own belt, and doing so will cause it to become soulbound. Requires at least 500 skill in Engineering to use." }
entries[84428] = { ["name"] = "Gnomish X-Ray Scope", ["text"] = "2 sec cast 4\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nHardened Elementium Bar (2), Dream Emerald (2)\nGnomish X-Ray Scope\n80\nUse: Attaches a permanent scope to a bow or gun that sometimes increases ranged attack power by 800 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound." }
entries[84429] = { ["name"] = "Goblin Barbecue", ["text"] = "2 sec cast\nTools: High-Powered Bolt Gun , Arclight Spanner\nReagents:\nElementium Bar (2), Toughened Flesh (2), Lavascale Fillet (2)\n80\nRequires Cooking\n(475)\nUse: Set out the barbecue to feed your entire raid or party!\n\nRestores 67500 health and 45000 mana over 30 sec. If you spend at least 10 seconds eating you will become well fed and gain 60 Stamina and 60 in another useful stat for 1 hour." }
entries[84430] = { ["name"] = "Heat-Treated Spinning Lure", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Obsidium Bolts , Elementium Bar (4), Volatile Fire\n(2)\nRequires Fishing\n(250)\nUse: When applied to your fishing pole, increases Fishing by 150 for 15 minutes.\n\"Even works in lava!\"" }
entries[84431] = { ["name"] = "Overpowered Chicken Splitter", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Elementium Bar (12), Truegold (2), Handful of Obsidium Bolts (6), Electrified Ether (8), Chaos Orb\nOverpowered Chicken Splitter\nBinds when equipped\nRanged Bow\n1,082 - 2,010 Damage Speed 2.80\n(552.14 damage per second)\n+95 Agility\n+143 Stamina\nDurability 75 / 75\n85\nEquip: Improves critical strike rating by 68.\nEquip: Improves haste rating by 56." }
entries[84432] = { ["name"] = "Kickback 5000", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Elementium Bar (9), Truegold (3), Hair Trigger , Walnut Stock , Chaos Orb\nKickback 5000\nBinds when equipped\nRanged Gun\n1,082 - 2,010 Damage Speed 2.80\n(552.14 damage per second)\n+75 Agility\n+143 Stamina\n\nRed Socket\nSocket Bonus: +10 Agility\n\nDurability 75 / 75\n85\nEquip: Improves critical strike rating by 65.\nEquip: Improves haste rating by 42." }
